10	/**
11	 * Assigns the owner's {@code customerCode} as {@code <REGION>-<HASH8>}, dropping the old per-city
12	 * sequence. REGION is the region code derived from the postcode (2xxx→NSW, 3xxx→VIC, 4xxx→QLD, then
13	 * by city, else UNKNOWN); HASH8 is the first 8 upper-case hex characters of SHA-256 over the
14	 * normalized (E.164) telephone concatenated with the last name.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner) {
19	        String pc = owner.getPostcode();
20	        String city = owner.getCity();
21	        String region;
22	        if (pc != null && pc.matches("20\\d{2}")) {
23	            region = "NSW";
24	        }
25	        else if (pc != null && pc.matches("30\\d{2}")) {
26	            region = "VIC";
27	        }
28	        else if (pc != null && pc.matches("40\\d{2}")) {
29	            region = "QLD";
30	        }
31	        else if ("Sydney".equals(city)) {
32	            region = "NSW";
33	        }
34	        else if ("Melbourne".equals(city)) {
35	            region = "VIC";
36	        }
37	        else if ("Brisbane".equals(city)) {
38	            region = "QLD";
39	        }
40	        else {
41	            region = "UNKNOWN";
42	        }
43	        byte[] digest;
44	        try {
45	            digest = MessageDigest.getInstance("SHA-256")
46	                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
47	        }
48	        catch (NoSuchAlgorithmException ex) {
49	            throw new IllegalStateException(ex);
50	        }
51	        StringBuilder hash8 = new StringBuilder(8);
52	        for (int i = 0; i < 4; i++) {
53	            hash8.append(String.format("%02X", digest[i]));
54	        }
55	        owner.setCustomerCode(region + "-" + hash8);
56	    }
57	}
